import { ArrowRight, CheckCircle2, CircleHelp, ShieldCheck, UsersRound } from "lucide-react";
import { Link } from "react-router-dom";
import { PageHeader } from "../components/content/page-elements";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "../components/ui/accordion";
import { Button } from "../components/ui/button";
import { departments, faqs } from "../data/site-data";
import { CandidateForm } from "../features/recruitment/candidate-form";
import { fetchRecruitmentForm } from "../features/recruitment/api";
import type { RecruitmentFormConfig } from "../features/recruitment/types";
import { useEffect, useState } from "react";

export function JoinPage() {
  const [formConfig, setFormConfig] = useState<RecruitmentFormConfig | null>(null);
  const [formStatusLoading, setFormStatusLoading] = useState(true);
  const [formStatusError, setFormStatusError] = useState("");

  useEffect(() => {
    let active = true;
    fetchRecruitmentForm().then((config) => { if (active) setFormConfig(config); })
      .catch((error: unknown) => { if (active) setFormStatusError(error instanceof Error ? error.message : "Không thể kiểm tra trạng thái tuyển thành viên."); })
      .finally(() => { if (active) setFormStatusLoading(false); });
    return () => { active = false; };
  }, []);

  const canApply = formConfig?.source === "google-sheet" && formConfig.isOpen;
  const statusText = formStatusLoading
    ? "Đang tải trạng thái tuyển thành viên…"
    : formStatusError
      ? "Chưa thể kiểm tra trạng thái đợt tuyển. Vui lòng xem lại sau."
      : formConfig?.source === "prototype"
        ? import.meta.env.DEV ? "Đây là biểu mẫu xem thử local; dữ liệu không được gửi tới VIC." : "Backend tuyển thành viên chưa được kết nối; hiện chưa thể nhận đơn."
        : formConfig?.isOpen
          ? "VIC đang mở đợt tuyển thành viên."
          : formConfig?.closedMessage ?? "Chưa có thông tin đợt tuyển.";
  return <main id="main"><PageHeader eyebrow="THAM GIA VIC" title={<>Bạn không cần biết hết.<br />Chỉ cần muốn bắt đầu.</>} description="Nếu bạn thích công nghệ, muốn thử một điều mới hoặc tìm những người cùng học, VIC có thể là nơi để bạn bắt đầu.">{canApply && <Button asChild><a href="#application-form">Gửi đăng ký <ArrowRight size={17} /></a></Button>}</PageHeader>
    <section className="section-space relative overflow-hidden" aria-labelledby="join-form-title"><div className="pointer-events-none absolute left-1/2 top-1/4 size-[34rem] -translate-x-1/2 rounded-full bg-vic-blue/10 blur-3xl" /><div className="page-container relative"><div className="mx-auto mb-9 max-w-[48rem]"><p className="section-label">01 / ĐƠN ỨNG TUYỂN</p><h2 id="join-form-title" className="section-title">Bắt đầu câu chuyện của bạn với VIC.</h2><p className="section-intro">Biểu mẫu được tải từ cấu hình tuyển thành viên. Câu trả lời chỉ được gửi khi bạn xác nhận ở bước xem lại.</p><div className="mt-5 inline-flex items-center gap-2 rounded-full bg-vic-blue-soft px-4 py-2 text-sm font-semibold text-vic-blue"><ShieldCheck size={16} /> Không lưu câu trả lời trong localStorage</div></div><div className="mx-auto max-w-[48rem]"><CandidateForm /></div></div></section>
    <section className="section-space"><div className="page-container"><div className="grid gap-5 md:grid-cols-3">{[{ icon: UsersRound, title: "Bạn đồng hành", text: "Kết nối với những người cũng đang học, thử và hoàn thiện kỹ năng." }, { icon: CheckCircle2, title: "Trải nghiệm thực hành", text: "Tham gia những hoạt động và sản phẩm phù hợp với khả năng hiện tại." }, { icon: CircleHelp, title: "Không gian đặt câu hỏi", text: "Bắt đầu từ điều chưa rõ và cùng nhau tìm cách giải quyết." }].map(({ icon: Icon, title, text }) => <article key={title} className="glass-surface rounded-[2rem] p-7"><Icon className="text-vic-blue" /><h2 className="mt-8 text-xl font-semibold">{title}</h2><p className="mt-3 text-sm leading-7 text-vic-muted">{text}</p></article>)}</div></div></section>
    <section className="section-space bg-vic-surface"><div className="page-container"><p className="section-label">02 / CHỌN KHÔNG GIAN</p><div className="grid gap-6 md:grid-cols-2">{departments.map((department) => <Link key={department.id} to={`/${department.slug}`} className="interactive-card rounded-[2rem] bg-white p-8"><h2 className="text-2xl font-semibold">{department.name}</h2><p className="mt-3 leading-7 text-vic-muted">{department.summary}</p><span className="mt-6 inline-flex items-center gap-2 font-semibold text-vic-blue">Tìm hiểu ban <ArrowRight size={16} /></span></Link>)}</div></div></section>
    <section className="section-space"><div className="page-container grid gap-12 lg:grid-cols-[.8fr_1.2fr]"><div><p className="section-label">03 / CÁC BƯỚC</p><h2 className="section-title">Từ tìm hiểu đến kết nối.</h2></div><ol className="space-y-4">{["Tìm hiểu VIC và hai ban.", "Theo dõi thông tin khi VIC mở đợt tuyển.", "Gửi đăng ký qua biểu mẫu chính thức nếu có.", "Kết nối và tham gia hoạt động phù hợp."].map((step, index) => <li key={step} className="grid grid-cols-[2.75rem_1fr] items-center gap-4 border-b border-black/10 pb-4"><span className="font-mono text-sm font-semibold text-vic-blue">0{index + 1}</span><span>{step}</span></li>)}</ol></div></section>
    <section className="section-space bg-vic-ink text-white"><div className="page-container grid gap-10 lg:grid-cols-2"><div><p className="font-mono text-xs font-semibold text-[#8ea8ff]">TRẠNG THÁI TUYỂN THÀNH VIÊN</p><h2 className="mt-5 text-3xl font-bold tracking-[-.04em]" role={formStatusError ? "status" : undefined}>{statusText}</h2><p className="mt-4 text-sm leading-7 text-white/60">Thông tin trong biểu mẫu được dùng để tiếp nhận đơn ứng tuyển và liên hệ về đợt tuyển thành viên VIC.</p></div><div><p className="mb-4 font-mono text-xs font-semibold text-[#8ea8ff]">KÊNH LIÊN HỆ</p>{formConfig?.contactEmail || formConfig?.facebookUrl ? <div className="flex flex-wrap gap-x-5 gap-y-2 text-white/75">{formConfig.contactEmail && <a className="hover:text-white" href={`mailto:${formConfig.contactEmail}`}>{formConfig.contactEmail}</a>}{formConfig.facebookUrl && <a className="hover:text-white" href={formConfig.facebookUrl} target="_blank" rel="noreferrer">Facebook VIC</a>}</div> : <p className="text-white/65">Kênh liên hệ sẽ hiển thị tại đây khi được VIC cập nhật.</p>}</div></div></section>
    <section className="section-space"><div className="page-container grid gap-12 lg:grid-cols-[.7fr_1.3fr]"><div><p className="section-label">04 / FAQ</p><h2 className="section-title">Một vài điều bạn có thể đang hỏi.</h2></div><Accordion type="single" collapsible className="border-t border-black/10">{faqs.map((item) => <AccordionItem key={item.id} value={item.id}><AccordionTrigger>{item.question}</AccordionTrigger><AccordionContent>{item.answer}</AccordionContent></AccordionItem>)}</Accordion></div></section>
  </main>;
}
